export async function getInitializeMarketInstructionAsync<
  TAccountAdmin extends string,
  TAccountProtocol extends string,
  TAccountMarket extends string,
  TAccountSystemProgram extends string,
  TProgramAddress extends Address = typeof SOLFX_CORE_PROGRAM_ADDRESS,
>(
  input: InitializeMarketAsyncInput<
    TAccountAdmin,
    TAccountProtocol,
    TAccountMarket,
    TAccountSystemProgram
  >,
  config?: { programAddress?: TProgramAddress },
): Promise<
  InitializeMarketInstruction<
    TProgramAddress,
    TAccountAdmin,
    TAccountProtocol,
    TAccountMarket,
    TAccountSystemProgram
  >
> {
  // Program address.
  const programAddress = config?.programAddress ?? SOLFX_CORE_PROGRAM_ADDRESS;

  // Original accounts.
  const originalAccounts = {
    admin: { value: input.admin ?? null, isWritable: true },
    protocol: { value: input.protocol ?? null, isWritable: true },
    market: { value: input.market ?? null, isWritable: true },
    systemProgram: { value: input.systemProgram ?? null, isWritable: false },
  };
  const accounts = originalAccounts as Record<
    keyof typeof originalAccounts,
    ResolvedAccount
  >;

  // Original args.
  const args = { ...input };

  // Resolve default values.
  if (!accounts.protocol.value) {
    accounts.protocol.value = await findProtocolPda();
  }
  if (!accounts.market.value) {
    accounts.market.value = await findMarketPda({
      marketIndex: expectSome(args.marketIndex),
    });
  }
  if (!accounts.systemProgram.value) {
    accounts.systemProgram.value =
      "11111111111111111111111111111111" as Address<"11111111111111111111111111111111">;
  }

  const getAccountMeta = getAccountMetaFactory(programAddress, "programId");
  return Object.freeze({
    accounts: [
      getAccountMeta(accounts.admin),
      getAccountMeta(accounts.protocol),
      getAccountMeta(accounts.market),
      getAccountMeta(accounts.systemProgram),
    ],
    data: getInitializeMarketInstructionDataEncoder().encode(
      args as InitializeMarketInstructionDataArgs,
    ),
    programAddress,
  } as InitializeMarketInstruction<
    TProgramAddress,
    TAccountAdmin,
    TAccountProtocol,
    TAccountMarket,
    TAccountSystemProgram
  >);
}

